-- Generated from actual acquired and processed schemas. Separate cohorts stay in separate schemas.
CREATE SCHEMA IF NOT EXISTS "cs_gb_2024";
CREATE TABLE IF NOT EXISTS "cs_gb_2024"."collision" ("collision_index" text, "collision_year" text, "collision_ref_no" text, "location_easting_osgr" text, "location_northing_osgr" text, "longitude" text, "latitude" text, "police_force" text, "collision_severity" text, "number_of_vehicles" text, "number_of_casualties" text, "date" text, "day_of_week" text, "time" text, "local_authority_district" text, "local_authority_ons_district" text, "local_authority_highway" text, "local_authority_highway_current" text, "first_road_class" text, "first_road_number" text, "road_type" text, "speed_limit" text, "junction_detail_historic" text, "junction_detail" text, "junction_control" text, "second_road_class" text, "second_road_number" text, "pedestrian_crossing_human_control_historic" text, "pedestrian_crossing_physical_facilities_historic" text, "pedestrian_crossing" text, "light_conditions" text, "weather_conditions" text, "road_surface_conditions" text, "special_conditions_at_site" text, "carriageway_hazards_historic" text, "carriageway_hazards" text, "urban_or_rural_area" text, "did_police_officer_attend_scene_of_accident" text, "trunk_road_flag" text, "lsoa_of_accident_location" text, "enhanced_severity_collision" text, "collision_injury_based" text, "collision_adjusted_severity_serious" text, "collision_adjusted_severity_slight" text, "source_record_number" text, "collision_datetime_local" text);
ALTER TABLE "cs_gb_2024"."collision" ADD COLUMN IF NOT EXISTS geom geometry(Point,4326) GENERATED ALWAYS AS (cascadeshield_meta.wgs84_point("latitude","longitude")) STORED;
CREATE INDEX IF NOT EXISTS "collision_geom_idx" ON "cs_gb_2024"."collision" USING gist(geom);
CREATE OR REPLACE VIEW "cs_gb_2024"."collision_typed" AS SELECT t.*, NULLIF(t.collision_datetime_local,'')::timestamp AS collision_time_local FROM "cs_gb_2024"."collision" t;
CREATE INDEX IF NOT EXISTS "collision_collision_index_idx" ON "cs_gb_2024"."collision" ("collision_index");
CREATE SCHEMA IF NOT EXISTS "cs_gb_2024";
CREATE TABLE IF NOT EXISTS "cs_gb_2024"."vehicle" ("collision_index" text, "collision_year" text, "collision_ref_no" text, "vehicle_reference" text, "vehicle_type" text, "towing_and_articulation" text, "vehicle_manoeuvre_historic" text, "vehicle_manoeuvre" text, "vehicle_direction_from" text, "vehicle_direction_to" text, "vehicle_location_restricted_lane_historic" text, "vehicle_location_restricted_lane" text, "junction_location" text, "skidding_and_overturning" text, "hit_object_in_carriageway" text, "vehicle_leaving_carriageway" text, "hit_object_off_carriageway" text, "first_point_of_impact" text, "vehicle_left_hand_drive" text, "journey_purpose_of_driver_historic" text, "journey_purpose_of_driver" text, "sex_of_driver" text, "age_of_driver" text, "age_band_of_driver" text, "engine_capacity_cc" text, "propulsion_code" text, "age_of_vehicle" text, "generic_make_model" text, "driver_imd_decile" text, "lsoa_of_driver" text, "escooter_flag" text, "driver_distance_banding" text, "source_record_number" text);
CREATE OR REPLACE VIEW "cs_gb_2024"."vehicle_typed" AS SELECT t.* FROM "cs_gb_2024"."vehicle" t;
CREATE INDEX IF NOT EXISTS "vehicle_collision_index_idx" ON "cs_gb_2024"."vehicle" ("collision_index");
CREATE SCHEMA IF NOT EXISTS "cs_gb_2024";
CREATE TABLE IF NOT EXISTS "cs_gb_2024"."casualty" ("collision_index" text, "collision_year" text, "collision_ref_no" text, "vehicle_reference" text, "casualty_reference" text, "casualty_class" text, "sex_of_casualty" text, "age_of_casualty" text, "age_band_of_casualty" text, "casualty_severity" text, "pedestrian_location" text, "pedestrian_movement" text, "car_passenger" text, "bus_or_coach_passenger" text, "pedestrian_road_maintenance_worker" text, "casualty_type" text, "casualty_imd_decile" text, "lsoa_of_casualty" text, "enhanced_casualty_severity" text, "casualty_injury_based" text, "casualty_adjusted_severity_serious" text, "casualty_adjusted_severity_slight" text, "casualty_distance_banding" text, "escooter_flag" text, "source_record_number" text);
CREATE OR REPLACE VIEW "cs_gb_2024"."casualty_typed" AS SELECT t.* FROM "cs_gb_2024"."casualty" t;
CREATE INDEX IF NOT EXISTS "casualty_collision_index_idx" ON "cs_gb_2024"."casualty" ("collision_index");
