ALTER TABLE "cs_birmingham_2024"."osm_segments" ADD COLUMN IF NOT EXISTS geom geometry(LineString,4326) GENERATED ALWAYS AS (CASE WHEN cascadeshield_meta.wgs84_point("from_latitude","from_longitude") IS NOT NULL AND cascadeshield_meta.wgs84_point("to_latitude","to_longitude") IS NOT NULL THEN ST_MakeLine(cascadeshield_meta.wgs84_point("from_latitude","from_longitude"),cascadeshield_meta.wgs84_point("to_latitude","to_longitude")) ELSE NULL END) STORED;
