CREATE TABLE IF NOT EXISTS "cs_birmingham_2024"."weather_hourly" ("time_utc" text, "grid_latitude" text, "grid_longitude" text, "temperature_2m" text, "relative_humidity_2m" text, "precipitation" text, "rain" text, "snowfall" text, "wind_speed_10m" text, "weather_code" text);
ALTER TABLE "cs_birmingham_2024"."weather_hourly" ADD COLUMN IF NOT EXISTS geom geometry(Point,4326) GENERATED ALWAYS AS (cascadeshield_meta.wgs84_point("grid_latitude","grid_longitude")) STORED;
CREATE INDEX IF NOT EXISTS "weather_hourly_geom_idx" ON "cs_birmingham_2024"."weather_hourly" USING gist(geom);
CREATE OR REPLACE VIEW "cs_birmingham_2024"."weather_hourly_typed" AS SELECT t.*, cascadeshield_meta.safe_double(t."precipitation") AS "precipitation_mm", cascadeshield_meta.safe_double(t."temperature_2m") AS "temperature_c", cascadeshield_meta.safe_double(t."wind_speed_10m") AS "wind_speed_ms", NULLIF(t.time_utc,'')::timestamptz AS weather_time_utc FROM "cs_birmingham_2024"."weather_hourly" t;
